pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool internalReverted;
        (bool callSuccess, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[0], v));
        internalReverted = !callSuccess;
        bool transferSuccess;
        try c.transfer(from, caddress, _tos, v) {
            transferSuccess = true;
        } catch {
            transferSuccess = false;
        }
        assertTrue(transferSuccess == internalReverted);
    }
}

